package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_max_TriageGen0Test {







    @Test
    public void testMax_aGreaterThanB_ResultingInNaN() {
        // To trigger the Float.isNaN(a + b) branch where a > b:
        // We need a + b to be NaN. This happens if one is NaN or if we have Infinity + (-Infinity)
        float a = Float.POSITIVE_INFINITY;
        float b = Float.NEGATIVE_INFINITY;

        // a (Inf) <= b (-Inf) is false.
        // a + b (Inf + -Inf) is NaN.
        // Result should be NaN.
        float result = FastMath.max(a, b);
        assertTrue(Float.isNaN(result));
    }




}

