package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_max_TriageGen0Test {











    @Test
    public void testMax_WithNaN() {
        // If b is NaN, a <= b is false.
        // a + b is NaN.
        // Returns NaN.
        float a = 1.0f;
        float b = Float.NaN;
        assertTrue(Float.isNaN(FastMath.max(a, b)));

        // If a is NaN, a <= b is false.
        // a + b is NaN.
        // Returns NaN.
        float a2 = Float.NaN;
        float b2 = 1.0f;
        assertTrue(Float.isNaN(FastMath.max(a2, b2)));
    }
}
